public function test_user_cannot_edit_post_owned_by_other_user(): void
{
    $owner = User::factory()->create();
    $other = User::factory()->create();
    $post = Post::factory()->for($owner)->create();
    $this->actingAs($other)
        ->get(route('posts.edit', $post))
        ->assertForbidden();
}
